        customers = []

    seen = set()
    unassigned = []
    for c in customers:
        if c != depot and c not in seen:
            seen.add(c)
            unassigned.append(c)

    def demand_of(i):
        if demands is None:
            return 0
        if isinstance(demands, dict):
            return demands.get(i, 0)
        if isinstance(demands, (list, tuple)) and isinstance(i, int) and 0 <= i < len(demands):
            return demands[i]
        return 0

    def d(i, j):
        if dist_matrix is not None:
            if isinstance(dist_matrix, dict):
                row = dist_matrix.get(i)
                if isinstance(row, dict) and j in row:
                    return row[j]
                row = dist_matrix.get(j)
                if isinstance(row, dict) and i in row:
                    return row[i]
            elif isinstance(dist_matrix, (list, tuple)):
                return dist_matrix[i][j]
        if coords is not None:
            if isinstance(coords, dict):
                return dist_xy(coords[i], coords[j])
            return dist_xy(coords[i], coords[j])
        return 0

    total_demand = 0
    max_dem = 0
    for c in unassigned:
        dm = demand_of(c)
        if dm > max_dem:
            max_dem = dm
        if dm > 0:
            total_demand += dm
    if capacity is None:
        capacity = total_demand if total_demand > 0 else 10 ** 18
    if capacity <= 0:
        capacity = 10 ** 18

    # If any customer exceeds capacity, still place them alone to preserve completeness.
    oversized = [c for c in unassigned if demand_of(c) > capacity]
    normal = [c for c in unassigned if demand_of(c) <= capacity]

    def route_load(route):
        s = 0
        for c in route:
            s += demand_of(c)
        return s

    def route_cost(route):
        if not route:
            return 0
        cst = d(depot, route[0])
        for i in range(len(route) - 1):
            cst += d(route[i], route[i + 1])
        cst += d(route[-1], depot)
        return cst

    def best_insertion_pos(route, node):
        if not route:
            return 0, 0
        best_pos = 0
        best_delta = d(depot, node) + d(node, route[0]) - d(depot, route[0])
        prev = route[0]
        for i in range(1, len(route)):
            cur = route[i]
            delta = d(prev, node) + d(node, cur) - d(prev, cur)
            if delta < best_delta or (delta == best_delta and i < best_pos):
                best_delta = delta
                best_pos = i
            prev = cur
        delta_end = d(route[-1], node) + d(node, depot) - d(route[-1], depot)
        if delta_end < best_delta or (delta_end == best_delta and len(route) < best_pos):
            best_delta = delta_end
            best_pos = len(route)
        return best_pos, best_delta

    # Construct routes by regret-2 insertion from a seed.
