                route = route[:best_i] + route[best_i:best_j + 1][::-1] + route[best_j + 1:]
                improved = True
        return route

    routes = [two_opt(r[:]) for r in routes]

    # Cross-route relocate improvement
    improved = True
    while improved:
        improved = False
        best_move = None
        for i in range(len(routes)):
            ri = routes[i]
            load_i = route_load(ri)
            for p in range(len(ri)):
